`timescale 1ns/1ps
module xsil_pcpi (
  input             clk,
  input             resetn,

  // Standard PicoRV32 PCPI
  input             pcpi_valid,
  input      [31:0] pcpi_insn,
  input      [31:0] pcpi_rs1,
  input      [31:0] pcpi_rs2,
  output reg        pcpi_wr,
  output reg [31:0] pcpi_rd,
  output reg        pcpi_wait,
  output reg        pcpi_ready,

  // Adapter port: current destination-register value (rd-as-source).
  // Stock PicoRV32 does not provide this; RF tap required for full-core use.
  input      [31:0] pcpi_rsd
);

  localparam S_IDLE = 2'd0;
  localparam S_BUSY = 2'd1;
  localparam S_DONE = 2'd2;

  // Shared IR helpers (used when an instruction's expression references them).
  function automatic [31:0] xsil_clz;
    input [31:0] a;
    integer i;
    reg found;
    begin
      xsil_clz = 32'd32;
      found = 1'b0;
      for (i = 31; i >= 0; i = i - 1) begin
        if (!found && a[i]) begin
          xsil_clz = 31 - i;
          found = 1'b1;
        end
      end
    end
  endfunction

  // Combinational decode of the live instruction word.
  wire match_xmac = pcpi_valid && ((pcpi_insn & 32'hfe00707f) == 32'h0200000b);
  wire match_any = match_xmac;

  reg match_xmac_q;
  reg [31:0] rs1_q, rs2_q, rsd_q;
  reg [31:0] result_d;
  reg [1:0]  state;

  // Datapath: pure function of latched operands (IR-compiled).
  always @* begin
    result_d = 32'd0;
    case (1'b1)
      match_xmac_q: result_d = ((rsd_q) + (((rs1_q) * (rs2_q))));
      default: result_d = 32'd0;
    endcase
  end

  always @(posedge clk) begin
    if (!resetn) begin
      state <= S_IDLE;
      pcpi_wait <= 1'b0;
      pcpi_ready <= 1'b0;
      pcpi_wr <= 1'b0;
      pcpi_rd <= 32'd0;
      rs1_q <= 32'd0;
      rs2_q <= 32'd0;
      rsd_q <= 32'd0;
      match_xmac_q <= 1'b0;
    end else begin
      // Defaults: ready/wr are single-cycle pulses.
      pcpi_ready <= 1'b0;
      pcpi_wr <= 1'b0;

      case (state)
        S_IDLE: begin
          pcpi_wait <= 1'b0;
          if (match_any) begin
            match_xmac_q <= match_xmac;
            rs1_q <= pcpi_rs1;
            rs2_q <= pcpi_rs2;
            rsd_q <= pcpi_rsd;
            pcpi_wait <= 1'b1;   // ack before the 16-cycle illegal timeout
            state <= S_BUSY;
          end
        end

        S_BUSY: begin
          // One compute cycle with stable latched operands.
          pcpi_wait <= 1'b1;
          state <= S_DONE;
        end

        S_DONE: begin
          pcpi_rd <= result_d;
          pcpi_wr <= 1'b1;
          pcpi_ready <= 1'b1;
          pcpi_wait <= 1'b0;
          match_xmac_q <= 1'b0;
          state <= S_IDLE;
        end

        default: state <= S_IDLE;
      endcase
    end
  end

endmodule
